 return card('Start & desktop',settingToggle('Full-screen Start','A larger app screen on desktop. Phones always use full screen.','startFullscreen')+settingToggle('Desktop shortcuts','Show Lite apps on the desktop.','desktopIcons')+settingToggle('Reduced motion','Keep window transitions still.','reduceMotion')+settingSelect('Taskbar alignment','Place Start and your app icons in the center or on the left.','taskbarAlignment',[['center','Center'],['left','Left']]))+card('Start pins','<p>Choose All apps in Start to pin your favorites. Use Edit pins to remove a pin.</p>'+btn('Customize Start','start','secondary'));
