let dragState=null;
function endWindowInteraction(cancel=false){if(dragFrame){cancelAnimationFrame(dragFrame);dragFrame=0;if(!cancel&&dragPoint)paintWindowDrag(dragPoint);}const d=dragState;dragState=null;document.documentElement.classList.remove('window-interaction');$('#snap-preview')?.remove();if(!d)return;const w=S.wins.find(w=>w.id===d.id);if(w&&d.layout&&!cancel){w.restoreBounds={x:d.x,y:d.y,w:d.w,h:d.h};applyWindowLayout(w,d.layout,innerWidth,innerHeight);}render();}
document.addEventListener('pointerdown',e=>{S.lastActivity=Date.now();if(S.lock)return;const section=e.target.closest('.window');if(section){const w=S.wins.find(w=>w.id===section.dataset.win);if(!w)return;if(S.active!==w.id){S.active=w.id;w.z=++S.z;document.querySelectorAll('.window.active').forEach(x=>x.classList.remove('active'));section.classList.add('active');section.style.zIndex=w.z;}const handle=e.target.closest('[data-resize]'),bar=e.target.closest('[data-drag]');if(e.button===0&&innerWidth>600&&(handle||bar&&!e.target.closest('button'))){if(w.max||w.snap){const box=section.getBoundingClientRect(),ratio=(e.clientX-box.left)/box.width;applyWindowLayout(w,'restore',innerWidth,innerHeight);if(bar){w.x=e.clientX-ratio*w.w;w.y=e.clientY-20;Object.assign(w,fitWindowBounds(w,innerWidth,innerHeight));}section.classList.remove('maximized','snapped');Object.assign(section.style,{left:w.x+'px',top:w.y+'px',width:w.w+'px',height:w.h+'px'});}dragState={id:w.id,resize:!!handle,startX:e.clientX,startY:e.clientY,x:w.x,y:w.y,w:w.w,h:w.h};document.documentElement.classList.add('window-interaction');try{(handle||bar).setPointerCapture(e.pointerId);}catch{}e.preventDefault();}}else if(!e.target.closest('.start-menu,.search-panel,.quick-panel,.calendar-panel,.task-view,.snap-menu,.context-menu,.taskbar,.modal')&&(S.menu||S.context||S.snapFor)){S.menu=null;S.context=null;S.snapFor=null;render();}});
function paintWindowDrag(e){if(!dragState)return;const d=dragState,w=S.wins.find(w=>w.id===d.id),el=document.querySelector(`[data-win="${d.id}"]`);if(!w||!el)return endWindowInteraction(true);const dx=e.clientX-d.startX,dy=e.clientY-d.startY;const bounds=fitWindowBounds(d.resize?{x:d.x,y:d.y,w:d.w+dx,h:d.h+dy}:{x:d.x+dx,y:d.y+dy,w:d.w,h:d.h},innerWidth,innerHeight);Object.assign(w,bounds);Object.assign(el.style,{left:w.x+'px',top:w.y+'px',width:w.w+'px',height:w.h+'px'});d.layout=!d.resize&&innerWidth>=720?(e.clientY<18?'max':e.clientX<18?'left':e.clientX>innerWidth-18?'right':null):null;if(d.layout){let preview=$('#snap-preview');if(!preview){preview=document.createElement('div');preview.id='snap-preview';preview.setAttribute('aria-hidden','true');$('#desktop').appendChild(preview);}const box=snapBounds(d.layout,innerWidth,innerHeight);Object.assign(preview.style,{left:box.x+'px',top:box.y+'px',width:box.w+'px',height:box.h+'px'});}else $('#snap-preview')?.remove();}
let dragFrame=0,dragPoint;document.addEventListener('pointermove',e=>{if(!dragState)return;dragPoint={clientX:e.clientX,clientY:e.clientY};if(!dragFrame)dragFrame=requestAnimationFrame(()=>{dragFrame=0;paintWindowDrag(dragPoint);});});

document.addEventListener('pointerup',()=>endWindowInteraction());document.addEventListener('pointercancel',()=>endWindowInteraction(true));
document.addEventListener('keydown',async e=>{S.lastActivity=Date.now();if(S.lock)return;if(e.key==='Escape'){if(S.modal)hideModal();else{S.menu=null;S.context=null;S.snapFor=null;render();}}if(e.key==='F9'){e.preventDefault();S.menu=S.menu==='tasks'?null:'tasks';S.context=null;S.snapFor=null;render();}if((e.ctrlKey||e.metaKey)&&e.code==='Space'){e.preventDefault();S.menu=S.menu==='start'?null:'start';S.startAll=false;S.query='';S.context=null;S.snapFor=null;render();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();S.menu='search';S.query='';render();$('#global-search')?.focus();}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&['notes','write','sheets'].includes(currentWin()?.app)){e.preventDefault();try{if(currentWin().app==='sheets')await saveSheet(currentWin());else await saveNote(currentWin());}catch(err){toast(err.message,true);}}if(e.target.id==='chat-input'&&e.key==='Enter'&&!e.shiftKey){e.preventDefault();await askAI(e.target.value);}});
window.addEventListener('beforeunload',e=>{if(S.wins.some(w=>['notes','write','sheets'].includes(w.app)&&!w.data.saved)){e.preventDefault();e.returnValue='';}});
window.addEventListener('online',()=>toast('You’re back online.'));window.addEventListener('offline',()=>toast('You’re offline. Guest files are still on this device.'));
setInterval(()=>{const now=new Date(),opts={hour:'numeric',minute:'2-digit',...(S.prefs.showSeconds?{second:'2-digit'}:{})};for(const id of ['desktop-time','tray-time','lock-time']){const el=$('#'+id);if(el&&!document.hidden){const text=now.toLocaleTimeString([],opts);if(el.textContent!==text)el.textContent=text;}}const minutes=Number(S.prefs.autoLockMinutes);if(!S.lock&&minutes>0&&Date.now()-S.lastActivity>minutes*60000)lock().catch(e=>toast(e.message,true));},1000);
function syncViewport(){document.documentElement.style.setProperty('--lite-height',(window.visualViewport?.height||innerHeight)+'px');}window.addEventListener('resize',syncViewport);window.visualViewport?.addEventListener('resize',syncViewport);syncViewport();
async function boot(){await loadGuest();try{const lockData=sessionStorage.getItem('liteos.lock');if(lockData){const saved=JSON.parse(lockData),profiles=(await localGet('accounts-v2'))?.users||[];if(profiles.some(u=>u.username===saved.username)){S.lockUser=saved;S.lock=true;}else sessionStorage.removeItem('liteos.lock');}try{const d=await api('/me');S.user=d.user;S.pol=d.policies;S.prefs={...defaults,...d.user.preferences};S.guest=false;await refreshFiles();}catch{}}catch{}await loadWallpaper();openApp(location.pathname==='/game-mode'?'heroes3':'home');api('/status').then(status=>{S.status=status;render();});storageHealth(navigator.storage).then(health=>S.health=health);}
boot().catch(e=>{console.error(e);$('#app').innerHTML='<div style="padding:35px;color:white"><h1>LiteOS</h1><p>'+H(storageMessage(e))+'</p><p>Try a regular browsing tab with storage enabled, or close other LiteOS tabs and retry.</p><a href="/" style="color:white">Reload LiteOS</a></div>';});
function renderShell(markup){
 const current=$('#desktop');if(!current){$('#app').innerHTML=markup;return;}
 const template=document.createElement('template');template.innerHTML=markup;const incoming=template.content.firstElementChild;
 const key=el=>el.dataset.win?'window:'+el.dataset.win:el.tagName+':'+el.classList.item(0);
 const old=new Map([...current.children].map(el=>[key(el),el])),keep=new Set();
 current.className=incoming.className;current.removeAttribute('style');
 for(const next of [...incoming.children]){const k=key(next),existing=old.get(k);keep.add(k);
  const w=next.dataset.win&&S.wins.find(w=>w.id===next.dataset.win);
  if(existing&&['apphost','browser','google','heroes3','litecraft'].includes(w?.app)&&existing.dataset.runToken===next.dataset.runToken){existing.className=next.className;existing.setAttribute('style',next.getAttribute('style')||'');existing.querySelector('.titlebar').innerHTML=next.querySelector('.titlebar').innerHTML;if(w.app==='litecraft'){const frame=existing.querySelector('iframe');frame?.contentWindow?.postMessage({type:'liteos:game-visibility',hidden:!!w.min},location.origin);frame?.contentWindow?.postMessage({type:'liteos:performance',mode:S.prefs.performanceMode},location.origin);}}
  else if(existing){const canvas=existing.querySelector('canvas[data-paint]');if(canvas&&canvas._liteImage===w?.data.image)next.querySelector('canvas[data-paint]')?.replaceWith(canvas);existing.replaceWith(next);}else current.appendChild(next);
 }
 for(const[k,el]of old)if(!keep.has(k))el.remove();
}
function launcherHTML(){const builtins=['litecraft','heroes3','write','sheets','google','notes','calc','paint','games','terminal'],installed=S.files.filter(f=>!f.trashed&&f.kind==='file'&&f.path.startsWith('/Home/Apps/')&&/\.(html?|liteapp)$/i.test(f.name));return `<div class="launcher-app"><div class="launcher-heading"><span><div class="eyebrow">RIGHT HERE IN YOUR SPACE</div><h2>Small apps. Ready to go.</h2><p>Your everyday tools run in LiteOS windows.</p></span>${T('apps')}</div><div class="section-heading"><h3>Made for LiteOS</h3><span class="pill">Runs inside the OS</span></div><div class="launcher-native-grid">${builtins.map(a=>`<button data-action="open" data-app="${a}" class="launcher-native">${T(a)}<strong>${H(apps[a].name)}</strong><small>${H(({litecraft:'Mine, build & explore a vast world',heroes3:'Your kingdom in the browser',write:'Documents & formatting',sheets:'Tables & formulas',google:'Search & Google apps',notes:'Quick text notes',calc:'Everyday arithmetic',paint:'Draw something new',photos:'Pictures & backgrounds',games:'Take a little break',terminal:'LiteScript commands'})[a])}</small></button>`).join('')}</div><div class="launcher-demo"><div class="web-logo">+1</div><span><h3>Your first imported app.</h3><p>Try Little Counter: a real HTML app running in an isolated LiteOS window.</p></span>${btn('Run demo','app-demo','')}</div><div class="section-heading"><h3>Your installed apps</h3>${btn(I('files')+'Manage','open','secondary small','data-app="files" data-path="/Home/Apps"')}</div>${installed.length?installed.map(f=>`<button class="launcher-installed" data-action="file-open" data-file="${f.id}">${T(/\.html?$/i.test(f.name)?'apphost':'browser')}<span><strong>${H(f.name.replace(/\.(html?|liteapp)$/i,''))}</strong><small>${/\.html?$/i.test(f.name)?'HTML app · Runs inside LiteOS':'Web app · Follows manifest launch mode'}</small></span>${I('chevron')}</button>`).join(''):'<p class="muted" style="font-size:13px">Import a single HTML file, create your own, or add a compatible web app.</p>'}<div class="launcher-actions">${btn(I('upload')+'Import app','app-import','secondary')}${btn(I('code')+'Create HTML app','app-create','secondary')}${btn('Explore web apps','open','secondary','data-app="store"')}</div></div>`;}
function appHostHTML(w){const d=w.data;return `<div class="app-host"><div class="toolbar"><span class="app-host-label">${I(d.kind==='html'?'code':'browser')}${d.kind==='html'?'Isolated HTML app':'Embedded web app'}</span><span class="toolbar-spacer"></span>${d.kind==='html'?'<button data-action="app-edit">'+I('code')+'Edit code</button>':`<button data-action="external" data-url="${H(d.url)}">${I('external')}Open tab</button>`}<button data-action="app-reload" title="Restart app">${I('refresh')}</button></div><iframe class="app-runner" data-app-frame="${w.id}" title="${H(d.name)}" src="${d.kind==='html'?'/sandbox.html#'+H(d.sandboxToken):H(d.url)}" sandbox="${d.kind==='html'?'allow-scripts allow-downloads':'allow-scripts allow-same-origin allow-forms allow-downloads allow-pointer-lock allow-presentation'}" referrerpolicy="no-referrer" allow="fullscreen; gamepad"></iframe></div>`;}
async function saveSheet(w){w.data.text=JSON.stringify({version:1,cells:w.data.cells},null,2);if(!/\.litesheet$/i.test(w.data.name))w.data.name+='.litesheet';await saveNote(w);}
function syncSheet(w){const section=document.querySelector(`[data-win="${w.id}"]`);if(!section)return;const selected=w.data.selected||'A1',formula=section.querySelector('[data-sheet-formula]');section.querySelector('[data-cell-label]').textContent=selected;if(document.activeElement!==formula)formula.value=w.data.cells[selected]||'';for(const input of section.querySelectorAll('[data-sheet-cell]')){const a=input.dataset.sheetCell;input.parentElement.classList.toggle('selected',a===selected);if(input!==document.activeElement)input.value=sheetValue(w.data.cells,a);}const label=section.querySelector('.editor-save-status');if(label)label.textContent=w.data.saved?'Saved':'Unsaved changes';}
document.addEventListener('focusin',e=>{const el=e.target;if(el.dataset.sheetCell){const w=winByEl(el);w.data.selected=el.dataset.sheetCell;el.value=w.data.cells[w.data.selected]||'';syncSheet(w);}});
document.addEventListener('focusout',e=>{if(e.target.dataset.sheetCell||e.target.hasAttribute('data-sheet-formula')){const w=winByEl(e.target);setTimeout(()=>syncSheet(w),0);}});
document.addEventListener('keydown',e=>{const el=e.target;if(e.key==='Enter'&&el.dataset.sheetCell){e.preventDefault();const a=el.dataset.sheetCell,row=Number(a.slice(1));el.blur();const next=el.closest('.window')?.querySelector(`[data-sheet-cell="${a[0]+Math.min(24,row+1)}"]`);next?.focus();}});
window.addEventListener('message',event=>{if(event.origin!=='null'||event.data?.type!=='liteos:sandbox-ready')return;for(const w of S.wins){if(w.app!=='apphost'||w.data.kind!=='html'||w.data.sandboxToken!==event.data.token)continue;const frame=document.querySelector(`iframe[data-app-frame="${w.id}"]`);if(frame?.contentWindow===event.source)event.source.postMessage({type:'liteos:launch',token:w.data.sandboxToken,html:w.data.content},'*');}});

function navigateBrowser(w,input){input=String(input||'').trim();let url='https://www.google.com/webhp?igu=1';if(input){if(/^https:\/\//i.test(input)){const u=new URL(input);if(u.username||u.password)throw Error('Use an HTTPS address without credentials.');if(u.origin===location.origin)throw Error('Open LiteOS apps from Start.');if(/^(www\.)?google\.com$/i.test(u.hostname)&&['/','/webhp','/search'].includes(u.pathname))u.searchParams.set('igu','1');url=u.href;}else url='https://www.google.com/search?igu=1&q='+encodeURIComponent(input);}w.data.browserURL=url;w.data.browserQuery=input;const frame=document.querySelector(`iframe[data-browser-frame="${w.id}"]`);if(frame)frame.src=url;const field=document.querySelector(`[data-win="${w.id}"] [name="query"]`);if(field)field.value=input;}

window.addEventListener('storage',async event=>{if(event.key==='liteos.storage-cleared'&&event.newValue){location.reload();return;}if(event.key!=='liteos.profile-update'||!S.user)return;try{const current=await deviceAccounts.request('/me');S.pol=current.policies;render();}catch{S.lockUser={username:S.user.username,display_name:S.user.display_name};S.user=null;S.files=[];S.wins=[];S.chat=[];S.aiCode=null;S.lock=true;render();}});

function heroesHTML(w){return `<iframe class="heroes-frame" data-heroes-frame="${w.id}" title="Heroes III library" src="/heroes3/index.html?profile=${encodeURIComponent(w.data.profile)}&token=${encodeURIComponent(w.data.gameToken)}" allow="fullscreen; gamepad; cross-origin-isolated" sandbox="allow-scripts allow-same-origin allow-forms allow-downloads allow-pointer-lock allow-modals"></iframe>`;}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.data?.type!=='liteos:heroes3')return;const w=S.wins.find(w=>w.app==='heroes3'&&w.data.gameToken===event.data.token);const frame=w&&document.querySelector(`iframe[data-heroes-frame="${w.id}"]`);if(!frame||frame.contentWindow!==event.source)return;S.lastActivity=Date.now();if(event.data.action==='game-mode'){if(S.wins.some(x=>['notes','write','sheets'].includes(x.app)&&!x.data.saved)){toast('Save open documents before entering game mode.',true);return;}location.href='/game-mode?app=heroes3';}else if(event.data.action==='desktop-mode'){if(S.wins.some(x=>['heroes3','litecraft'].includes(x.app)&&x.data.running)){toast('Save and close running games before leaving game mode.',true);return;}location.href='/';}else if(event.data.action==='download'){if(event.data.blob instanceof Blob&&['Heroes-III-Complete.zip','Heroes-III-saves.h3save'].includes(event.data.name))downloadBlob(event.data.blob,event.data.name);}else if(event.data.action==='running')w.data.running=true;else if(event.data.action==='stopped')w.data.running=false;});


function desktopContext(){return {state:S,apps,icon:I,tile:T,mark,displayName:displayName(),initials:initials(),recentHTML,canOpen:app=>['heroes3','litecraft'].includes(app)?allowed('allowGameRuntime'):app==='terminal'?allowed('allowTerminal'):['browser','google','remote'].includes(app)?allowed('allowExternalApps'):true};}
function requestCloseWindow(w){if(!w)return;if(['notes','write','sheets'].includes(w.app)&&!w.data.saved){showModal(`<h2>Keep this thought?</h2><p>You have unsaved changes in ${H(w.data.name)}.</p><div class="form-actions">${btn('Keep editing','modal-close','secondary')}${btn('Discard','discard-note','secondary')}${btn('Save & close','save-close-note','')}</div>`,'unsaved',{winId:w.id});}else closeWin(w.id);}
function toggleDesktop(){if(S.desktopRestore?.length&&S.wins.every(w=>w.min)){for(const w of S.wins)if(S.desktopRestore.includes(w.id))w.min=false;S.active=S.wins.filter(w=>!w.min).sort((a,b)=>b.z-a.z)[0]?.id;S.desktopRestore=null;}else{S.desktopRestore=S.wins.filter(w=>!w.min).map(w=>w.id);S.wins.forEach(w=>w.min=true);S.active=null;}S.menu=null;S.context=null;S.snapFor=null;render();}
function contextHTML(){const c=S.context;if(!c)return '';return `<section class="context-menu" style="left:${c.x}px;top:${c.y}px" aria-label="Desktop menu"><strong>${c.app?'Start app':'LiteOS desktop'}</strong>${c.app?`<button data-action="pin-start" data-app="${H(c.app)}">${I('pin')}${normalizePinnedApps(S.prefs.startPins).includes(c.app)?'Unpin from Start':'Pin to Start'}</button>`:`<button data-action="desktop-refresh">${I('refresh')}Refresh desktop</button><button data-action="task-view">${I('taskview')}Task View</button><button data-action="open" data-app="tasks">${I('tasks')}Task Manager</button><hr><button data-action="open" data-app="settings" data-category="personal" data-tab="wallpaper">${I('photos')}Personalize</button><button data-action="open" data-app="settings" data-category="system" data-tab="display">${I('display')}Display settings</button>`}</section>`;}
document.addEventListener('contextmenu',e=>{if(S.lock)return;const app=e.target.closest('.start-pin [data-app],.all-app-row [data-app]')?.dataset.app;if(!app&&e.target.closest('.window,.start-menu,.search-panel,.quick-panel,.calendar-panel,.task-view,.snap-menu,.modal'))return;if(!e.target.closest('#desktop'))return;e.preventDefault();S.menu=app?'start':null;S.snapFor=null;S.context={app:app&&Object.hasOwn(apps,app)?app:null,x:Math.max(8,Math.min(innerWidth-245,e.clientX)),y:Math.max(8,Math.min(innerHeight-330,e.clientY))};render();});
let refitTimer;addEventListener('resize',()=>{clearTimeout(refitTimer);refitTimer=setTimeout(()=>{if(dragState)return;for(const w of S.wins){if(w.max)continue;if(w.snap){const box=snapBounds(w.snap,innerWidth,innerHeight);Object.assign(w,{x:box.x,y:box.y,w:box.w,h:box.h,max:box.layout==='max',snap:box.layout==='max'?null:box.layout});}else Object.assign(w,fitWindowBounds(w,innerWidth,innerHeight));}S.snapFor=null;render();},120);});

function litecraftHTML(w){return `<iframe class="heroes-frame" data-litecraft-frame="${w.id}" title="LiteCraft" src="/litecraft/index.html?profile=${encodeURIComponent(w.data.profile)}&token=${encodeURIComponent(w.data.gameToken)}" allow="fullscreen" sandbox="allow-scripts allow-same-origin allow-downloads allow-pointer-lock allow-modals allow-forms"></iframe>`;}
window.addEventListener('message',event=>{if(event.origin!==location.origin||event.data?.type!=='liteos:litecraft')return;const w=S.wins.find(w=>w.app==='litecraft'&&w.data.gameToken===event.data.token),frame=w&&document.querySelector(`iframe[data-litecraft-frame="${w.id}"]`);if(!frame||frame.contentWindow!==event.source)return;S.lastActivity=Date.now();if(event.data.action==='running')w.data.running=true;if(event.data.action==='stopped')w.data.running=false;});

let fileFilterTimer;document.addEventListener('input',event=>{if(!event.target.hasAttribute('data-file-filter'))return;const input=event.target,w=winByEl(input);w.data.filter=input.value;w.data.page=0;clearTimeout(fileFilterTimer);fileFilterTimer=setTimeout(()=>{if(!S.wins.includes(w)||S.active!==w.id)return;const pos=input.selectionStart;render();const next=document.querySelector(`[data-win="${w.id}"] [data-file-filter]`);next?.focus();if(next?.type!=='search')next?.setSelectionRange(pos,pos);},120);});
for(const query of ['(prefers-color-scheme:dark)','(prefers-reduced-motion:reduce)'])matchMedia(query).addEventListener('change',applyPrefs);

addEventListener('message',event=>{if(event.origin!==location.origin||event.data?.type!=='liteos:performance-request')return;for(const win of S.wins.filter(w=>w.app==='litecraft')){const frame=document.querySelector(`[data-win="${win.id}"] iframe`);if(event.source===frame?.contentWindow)frame.contentWindow.postMessage({type:'liteos:performance',mode:S.prefs.performanceMode},location.origin);}});
